// T32 additive observer: no event validation or persistence replacement.
fn t32_observe(directory: &Path, stage: &str) {
    let wanted = std::env::var("CAL_T32_STOP_STAGE").unwrap_or_default();
    let family = std::env::var("CAL_T32_STOP_FAMILY").unwrap_or_default();
    if wanted != stage || directory.file_name().and_then(|n| n.to_str()) != Some(family.as_str()) { return; }
    let marker = std::env::var("CAL_T32_MARKER").expect("explicit owned marker");
    let mut file = OpenOptions::new().create_new(true).write(true).open(marker).expect("exclusive observer marker");
    file.write_all(stage.as_bytes()).expect("observer marker write");
    file.sync_all().expect("observer marker sync");
    loop { std::thread::sleep(std::time::Duration::from_secs(1)); }
}
